tests:
test({ sr: 'prvo slovo svake reči je veliko', en: 'the first letter of every word is capital' }, () => {
  expect(capitalizeWords('hello world')).toBe('Hello World');
});
test({ sr: 'ostala slova postaju mala', en: 'the other letters become lowercase' }, () => {
  expect(capitalizeWords('hELLO wORLD')).toBe('Hello World');
});
test({ sr: 'prazan tekst daje prazan tekst', en: 'empty text gives empty text' }, () => {
  expect(capitalizeWords('')).toBe('');
});

hiddenTests:
test('multiple spaces are preserved', () => {
  expect(capitalizeWords('a  b')).toBe('A  B');
});
test('a single letter', () => {
  expect(capitalizeWords('a')).toBe('A');
});
test('leading and trailing spaces are preserved', () => {
  expect(capitalizeWords(' hi there ')).toBe(' Hi There ');
});

solutions.code:
function capitalizeWords(text) {
  return text
    .split(' ')
    .map((word) => (word ? word[0].toUpperCase() + word.slice(1).toLowerCase() : word))
    .join(' ');
}
